-- Track the origin of availability rows generated by EXTRA_PERIOD exceptions.
-- Exceptions are deactivated instead of physically deleted so booked appointments remain untouched.

ALTER TABLE "schedule_exceptions"
ADD COLUMN "is_active" BOOLEAN NOT NULL DEFAULT true;

ALTER TABLE "availabilities"
ADD COLUMN "schedule_exception_id" TEXT;

-- Backfill rows generated by EXTRA_PERIOD exceptions that still exist.
UPDATE "availabilities" AS availability
SET "schedule_exception_id" = exception."id"
FROM "schedule_exceptions" AS exception
INNER JOIN "doctor_schedules" AS schedule
  ON schedule."id" = exception."schedule_id"
WHERE availability."doctorId" = schedule."doctorId"
  AND availability."date" = exception."date"
  AND exception."type" = 'EXTRA_PERIOD'
  AND exception."start_minute" IS NOT NULL
  AND exception."end_minute" IS NOT NULL
  AND availability."hourStart" =
      (exception."date"::timestamp + (exception."start_minute" - 60) * INTERVAL '1 minute')
  AND availability."hourEnd" =
      (exception."date"::timestamp + (exception."end_minute" - 60) * INTERVAL '1 minute')
  AND availability."schedule_exception_id" IS NULL;

CREATE INDEX "availabilities_schedule_exception_id_idx"
ON "availabilities"("schedule_exception_id");

ALTER TABLE "availabilities"
ADD CONSTRAINT "availabilities_schedule_exception_id_fkey"
FOREIGN KEY ("schedule_exception_id") REFERENCES "schedule_exceptions"("id")
ON DELETE SET NULL ON UPDATE CASCADE;
